function check(used: number, limit: number, exceeded = used > limit): LimitCheck {
  return {
    resource: "seats",
    plan: "starter",
    limit,
    used,
    remaining: Math.max(0, limit - used),
    .where(
      and(
        orgPredicate(activityEvents.orgId, orgId),
        eq(activityEvents.subjectKind, subjectKind),
