/** The picker speaks `YYYY-MM-DD`; the domain stores full ISO timestamps. */
export function toDateInputValue(
  value: IsoTimestamp | null,
  timeZone = "UTC",
): string | null {
  return value === null ? null : localDate(value, timeZone);
}

/**
 * The last instant of the picked local day, so the due date stays on that day
 * on the workspace clock however it is later read back.
 */
export function fromDateInputValue(
  value: string | null,
  timeZone = "UTC",
): IsoTimestamp | null {
  if (value === null || value.length === 0) return null;
  const nextDay = new Date(`${value}T00:00:00.000Z`);
  nextDay.setUTCDate(nextDay.getUTCDate() + 1);
  const startOfNextDay = startOfLocalDate(nextDay.toISOString().slice(0, 10), timeZone);
  return toIsoTimestamp(new Date(new Date(startOfNextDay).getTime() - 1));
}

