/**
 * Every workspace runs on its own clock: the `timeZone` setting, and the
 * calendar-day decisions taken on it — the overdue sweep and counters, the
 * digest schedule and window, and the retention cut-off.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runDigestEmailJob, shouldRunForOrg } from "@/server/jobs/digest-email-job";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as emailService from "@/server/services/email-service";
import { updateOrganization } from "@/server/services/organization-service";
import { getProject, listProjects } from "@/server/services/project-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

/** A tenant on `timeZone`, registered with the rollup so the jobs find it. */
async function makeTenant(slug: string, timeZone: string, extra = {}): Promise<Tenant> {
  const tenant = await createTenant(slug);
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { timeZone, ...extra },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function insertIssue(
  tenant: Tenant,
  dueAt: string | null,
  status: "backlog" | "done" = "backlog",
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  const issue = await issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, { dueAt }),
    tenant.userIds.owner,
    number,
  );
  if (status === "backlog") return issue;
  return issueRepo.updateIssue(tenant.org.id, issue.id, { status });
}

function collectOverdue(): string[] {
  const seen: string[] = [];
  detachers.push(subscribe("issue.overdue", (payload) => void seen.push(payload.issueId)));
  return seen;
}

describe("the timeZone setting", () => {
  it("defaults to UTC and is carried by every read", async () => {
    const tenant = await createTenant("tz-default");

    expect(tenant.org.settings.timeZone).toBe("UTC");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("UTC");
    expect((await orgRepo.findOrgBySlug("tz-default"))?.settings.timeZone).toBe("UTC");
    const listed = await orgRepo.listOrgsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === tenant.org.id)?.settings.timeZone).toBe("UTC");
  });

  it("is stored by updateOrg without disturbing the other settings", async () => {
    const tenant = await createTenant("tz-repo");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 5, enabledFlagOverrides: ["csv_export"] },
    });

    const updated = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { timeZone: "Asia/Tokyo" },
    });

    expect(updated.settings.timeZone).toBe("Asia/Tokyo");
    expect(updated.settings.digestHourUtc).toBe(5);
    expect(updated.settings.enabledFlagOverrides).toEqual(["csv_export"]);
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("Asia/Tokyo");

    // A patch that leaves the zone out keeps it.
    const later = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 6 },
    });
    expect(later.settings.timeZone).toBe("Asia/Tokyo");
  });

  it("is stored by updateOrganization", async () => {
    const tenant = await createTenant("tz-service");

    const updated = await updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { timeZone: "America/New_York" },
    });

    expect(updated.settings.timeZone).toBe("America/New_York");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("America/New_York");
  });

  it("refuses a zone Intl does not recognise, and changes nothing", async () => {
