describe("the digest window", () => {
  async function subscribe_(tenant: Tenant): Promise<void> {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      kind: "comment_created",
      inApp: false,
      email: false,
      digestOnly: true,
    });
  }

  async function notifyAt(tenant: Tenant, at: string, title: string): Promise<void> {
    vi.useFakeTimers();
    vi.setSystemTime(new Date(at));
    try {
      await notificationRepo.insertNotification(tenant.org.id, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.member,
        kind: "comment_created",
        title,
        body: title,
        href: "/issues/1",
        actorId: null,
        channels: ["email"],
      });
    } finally {
      vi.useRealTimers();
    }
  }

  function cell(html: string, key: string): string | null {
    return html.match(new RegExp(`<td>${key}</td><td>([^<]*)</td>`))?.[1] ?? null;
  }

  it("covers exactly the notifications created inside the local window", async () => {
    const tenant = await makeTenant("digest-tokyo", "Asia/Tokyo", { digestHourUtc: 8 });
    await subscribe_(tenant);

    // Window for a run at 08:30 JST on 2026-06-02: 08:00 JST the 1st .. 08:00 JST the 2nd
    // = 2026-05-31T23:00Z .. 2026-06-01T23:00Z.
    await notifyAt(tenant, "2026-05-31T22:00:00.000Z", "Before the window");
    await notifyAt(tenant, "2026-06-01T05:00:00.000Z", "Inside the window");
    await notifyAt(tenant, "2026-06-01T23:15:00.000Z", "After the window");

    const send = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    await runDigestEmailJob(new Date("2026-06-01T23:30:00.000Z"));

    expect(send).toHaveBeenCalledTimes(1);
    const html = send.mock.calls[0]?.[0].html ?? "";
    expect(cell(html, "entryCount")).toBe("1");
    expect(cell(html, "headline")).toBe("Inside the window");
    expect(cell(html, "windowStart")).toBe("2026-05-31T23:00:00.000Z");
    expect(cell(html, "windowEnd")).toBe("2026-06-01T23:00:00.000Z");

    // Newer notifications stay unread for the next digest; older ones were never touched.
    const unread = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: true,
      limit: 10,
    });
    expect(unread.items.map((item) => item.title).sort()).toEqual([
      "After the window",
      "Before the window",
    ]);

    // Once-only: a second tick in the same hour sends nothing.
    await runDigestEmailJob(new Date("2026-06-01T23:45:00.000Z"));
    expect(send).toHaveBeenCalledTimes(1);

    // The next day's digest picks the newer one up.
    await runDigestEmailJob(new Date("2026-06-02T23:30:00.000Z"));
    expect(send).toHaveBeenCalledTimes(2);
    expect(cell(send.mock.calls[1]?.[0].html ?? "", "headline")).toBe("After the window");
  });

  it("does not run outside the workspace's digest hour", async () => {
    const tenant = await makeTenant("digest-tokyo-off", "Asia/Tokyo", { digestHourUtc: 8 });
    await subscribe_(tenant);
    await notifyAt(tenant, "2026-06-01T05:00:00.000Z", "Waiting");

    const send = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    // 08:00 UTC is 17:00 in Tokyo.
    await runDigestEmailJob(new Date("2026-06-02T08:00:00.000Z"));

    expect(send).not.toHaveBeenCalled();
  });
});

describe("the retention cut-off", () => {
  async function activityAt(tenant: Tenant, at: string, summary: string): Promise<void> {
    await activityRepo.insertActivity({
      orgId: tenant.org.id,
      action: "issue.created",
      actorId: null,
      subjectKind: "issue",
      subjectId: summary,
      projectId: null,
      summary,
      metadata: {},
      occurredAt: toIsoTimestamp(new Date(at)),
    });
  }

  async function surviving(tenant: Tenant): Promise<string[]> {
    const page = await activityRepo.listActivity({ orgId: tenant.org.id, limit: 100, cursor: null });
    return page.items.map((item) => item.summary).filter((summary) => summary.startsWith("row:")).sort();
  }

  it("is local midnight retentionDays calendar days before today's local date", async () => {
    // Free plan keeps 30 days. Run at 05:00 JST on 2026-06-02: today's local date
    // is 06-02, 30 days earlier is 05-03, local midnight = 2026-05-02T15:00Z.
    const tenant = await makeTenant("retention-tokyo", "Asia/Tokyo");
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: {} });
    const free = await createTenantOnFreePlan("retention-free-tokyo", "Asia/Tokyo");

    await activityAt(free, "2026-05-02T14:00:00.000Z", "row:before");
    await activityAt(free, "2026-05-02T16:00:00.000Z", "row:after");

    await runCleanupArchivedJob(new Date("2026-06-01T20:00:00.000Z"));

    expect(await surviving(free)).toEqual(["row:after"]);
  });

  it("does not drift by an hour across a DST change", async () => {
    // Free plan, New York, run at noon on 2026-04-08: 30 days back is 03-09 (EDT),
    // local midnight = 2026-03-09T04:00Z — `30 × 24h` before now would be 03:00Z... on 03-09
    // but only because the clocks moved on 03-08; the calendar rule gives 04:00Z.
    const free = await createTenantOnFreePlan("retention-free-ny", "America/New_York");

    await activityAt(free, "2026-03-09T03:30:00.000Z", "row:before");
    await activityAt(free, "2026-03-09T04:30:00.000Z", "row:after");

    await runCleanupArchivedJob(new Date("2026-04-08T16:00:00.000Z"));

    expect(await surviving(free)).toEqual(["row:after"]);
  });

  async function createTenantOnFreePlan(slug: string, timeZone: string): Promise<Tenant> {
    const tenant = await createTenant(slug, "free");
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone } });
    await usageRepo.recomputeUsage(tenant.org.id);
    return tenant;
  }
});

