        orgId: tenant.org.id,
        name: "Renamed",
        settings: { timeZone: "Mars/Olympus", digestHourUtc: 3 },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    await expect(
      updateOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "Renamed",
        settings: { timeZone: "Mars/Olympus", digestHourUtc: 3 },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    const after = await orgRepo.findOrgById(tenant.org.id);
    expect(after?.name).toBe(tenant.org.name);
    expect(after?.settings.timeZone).toBe("Asia/Tokyo");
    expect(after?.settings.digestHourUtc).toBe(tenant.org.settings.digestHourUtc);
  });
});

