/**
 * Every workspace runs on its own clock: the `timeZone` setting, and the
 * calendar-day decisions taken on it — the overdue sweep and counters, the
 * digest schedule and window, and the retention cut-off.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runDigestEmailJob, shouldRunForOrg } from "@/server/jobs/digest-email-job";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as emailService from "@/server/services/email-service";
import { updateOrganization } from "@/server/services/organization-service";
import { getProject, listProjects } from "@/server/services/project-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.restoreAllMocks();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

/** A tenant on `timeZone`, registered with the rollup so the jobs find it. */
async function makeTenant(slug: string, timeZone: string, extra = {}): Promise<Tenant> {
  const tenant = await createTenant(slug);
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { timeZone, ...extra },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function insertIssue(
  tenant: Tenant,
  dueAt: string | null,
  status: "backlog" | "done" = "backlog",
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  const issue = await issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, { dueAt }),
    tenant.userIds.owner,
    number,
  );
  if (status === "backlog") return issue;
  return issueRepo.updateIssue(tenant.org.id, issue.id, { status });
}

function collectOverdue(): string[] {
  const seen: string[] = [];
  detachers.push(subscribe("issue.overdue", (payload) => void seen.push(payload.issueId)));
  return seen;
}

describe("the timeZone setting", () => {
  it("defaults to UTC and is carried by every read", async () => {
    const tenant = await createTenant("tz-default");

    expect(tenant.org.settings.timeZone).toBe("UTC");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("UTC");
    expect((await orgRepo.findOrgBySlug("tz-default"))?.settings.timeZone).toBe("UTC");
    const listed = await orgRepo.listOrgsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === tenant.org.id)?.settings.timeZone).toBe("UTC");
  });

  it("is stored by updateOrg without disturbing the other settings", async () => {
    const tenant = await createTenant("tz-repo");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 5, enabledFlagOverrides: ["csv_export"] },
    });

    const updated = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { timeZone: "Asia/Tokyo" },
    });

    expect(updated.settings.timeZone).toBe("Asia/Tokyo");
    expect(updated.settings.digestHourUtc).toBe(5);
    expect(updated.settings.enabledFlagOverrides).toEqual(["csv_export"]);
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("Asia/Tokyo");

    // A patch that leaves the zone out keeps it.
    const later = await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { digestHourUtc: 6 },
    });
    expect(later.settings.timeZone).toBe("Asia/Tokyo");
  });

  it("is stored by updateOrganization", async () => {
    const tenant = await createTenant("tz-service");

    const updated = await updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { timeZone: "America/New_York" },
    });

    expect(updated.settings.timeZone).toBe("America/New_York");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("America/New_York");
  });

  it("refuses a zone Intl does not recognise, and changes nothing", async () => {
    const tenant = await makeTenant("tz-invalid", "Asia/Tokyo");

    await expect(
      orgRepo.updateOrg(tenant.org.id, {
        orgId: tenant.org.id,
        name: "Renamed",
        settings: { timeZone: "Mars/Olympus", digestHourUtc: 3 },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    await expect(
      updateOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "Renamed",
        settings: { timeZone: "Mars/Olympus", digestHourUtc: 3 },
      }),
    ).rejects.toBeInstanceOf(RangeError);

    const after = await orgRepo.findOrgById(tenant.org.id);
    expect(after?.name).toBe(tenant.org.name);
    expect(after?.settings.timeZone).toBe("Asia/Tokyo");
    expect(after?.settings.digestHourUtc).toBe(tenant.org.settings.digestHourUtc);
  });
});

describe("the overdue sweep and counters", () => {
  // 2026-06-01T20:00Z is 05:00 on the 2nd in Tokyo and 16:00 on the 1st in New York.
  const DUE = "2026-06-01T20:00:00.000Z";

  it("takes the due day on the workspace clock", async () => {
    resetOverdueTracking();
    const tokyo = await makeTenant("overdue-tokyo", "Asia/Tokyo");
    const utc = await makeTenant("overdue-utc", "UTC");
    const newYork = await makeTenant("overdue-ny", "America/New_York");
    const tokyoIssue = await insertIssue(tokyo, DUE);
    const utcIssue = await insertIssue(utc, DUE);
    const nyIssue = await insertIssue(newYork, DUE);

    // 23:00 on the 2nd in Tokyo: the due day (the 2nd) is still running there.
    // UTC (the 2nd, 14:00) has ended the 1st; New York (10:00 on the 2nd) too.
    const seen = collectOverdue();
    await runOverdueIssueJob(new Date("2026-06-02T14:00:00.000Z"));
    expect(seen).toContain(utcIssue.id);
    expect(seen).toContain(nyIssue.id);
    expect(seen).not.toContain(tokyoIssue.id);

    // Once Tokyo's 2nd is over, it is overdue there too.
    await runOverdueIssueJob(new Date("2026-06-02T15:00:00.000Z"));
    expect(seen).toContain(tokyoIssue.id);
  });

  it("is not overdue during the due day itself, at any hour", async () => {
    resetOverdueTracking();
    const tenant = await makeTenant("overdue-same-day", "Asia/Tokyo");
    const issue = await insertIssue(tenant, "2026-06-01T15:00:00.000Z"); // 00:00 on the 2nd

    const seen = collectOverdue();
    await runOverdueIssueJob(new Date("2026-06-02T14:59:59.000Z"));
    expect(seen).not.toContain(issue.id);
    expect(
      (await issueRepo.listOverdueIssues(tenant.org.id, toIsoTimestamp(new Date("2026-06-02T14:59:59.000Z")), "Asia/Tokyo")).map((row) => row.id),
    ).not.toContain(issue.id);

    await runOverdueIssueJob(new Date("2026-06-02T15:00:00.000Z"));
    expect(seen).toContain(issue.id);
  });

  it("counts overdue issues in the project stats on the same rule", async () => {
    const tokyo = await makeTenant("stats-tokyo", "Asia/Tokyo");
    const utc = await makeTenant("stats-utc", "UTC");
    for (const tenant of [tokyo, utc]) {
      await insertIssue(tenant, "2026-01-01T00:00:00.000Z"); // long overdue
      await insertIssue(tenant, "2026-01-02T00:00:00.000Z", "done"); // closed: never overdue
      await insertIssue(tenant, null); // no due date
      await insertIssue(tenant, "2099-01-01T00:00:00.000Z"); // far future
    }
    // Due today on each workspace's clock (whatever time of day it names): not overdue yet.
    const at = (offsetHours: number) => new Date(Date.now() + offsetHours * 3_600_000).toISOString();
    await insertIssue(utc, new Date(new Date().setUTCHours(0, 0, 0, 0)).toISOString());
    await insertIssue(tokyo, at(0));

    const fromTokyo = await getProject(tokyo.actors.owner, tokyo.org.id, tokyo.project.slug);
    const fromUtc = await getProject(utc.actors.owner, utc.org.id, utc.project.slug);
    expect(fromTokyo.stats.overdueIssues).toBe(1);
    expect(fromUtc.stats.overdueIssues).toBe(1);

    const listed = await listProjects(tokyo.actors.owner, { orgId: tokyo.org.id, limit: 10 });
    expect(listed.items.find((item) => item.project.id === tokyo.project.id)?.stats.overdueIssues).toBe(1);
  });

  it("evaluates the counter at the moment it runs", async () => {
    const tenant = await makeTenant("stats-moment", "Asia/Tokyo");
    await insertIssue(tenant, "2026-06-01T20:00:00.000Z"); // the 2nd in Tokyo

    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-06-02T14:59:00.000Z"));
    const during = await getProject(tenant.actors.owner, tenant.org.id, tenant.project.slug);
    vi.setSystemTime(new Date("2026-06-02T15:00:00.000Z"));
    const after = await getProject(tenant.actors.owner, tenant.org.id, tenant.project.slug);

    expect(during.stats.overdueIssues).toBe(0);
    expect(after.stats.overdueIssues).toBe(1);
  });
});

describe("the digest schedule", () => {
  it("runs during the hour the workspace clock shows", async () => {
    const tenant = await makeTenant("schedule-tokyo", "Asia/Tokyo", { digestHourUtc: 8 });
    const org = (await orgRepo.findOrgById(tenant.org.id))!;

    // 08:30 in Tokyo is 23:30Z the day before.
