    expect(shouldRunForOrg(org, new Date("2026-07-15T12:10:00.000Z"))).toBe(true); // EDT
    expect(shouldRunForOrg(org, new Date("2026-07-15T13:10:00.000Z"))).toBe(false);
  });
});

