/** Organization settings validation, including the workspace time zone. */
import { describe, expect, it } from "vitest";
import {
  organizationSettingsSchema,
  updateOrganizationSchema,
} from "@/schemas/organization";
import { ORG_A } from "../helpers/factories";

describe("schemas/organization", () => {
  it("defaults the time zone to UTC", () => {
    expect(organizationSettingsSchema.parse({})).toMatchObject({
      timeZone: "UTC",
      digestHourUtc: 7,
    });
  });

  it("accepts IANA zone names", () => {
    for (const timeZone of ["UTC", "Asia/Tokyo", "America/New_York", "Australia/Lord_Howe"]) {
      expect(organizationSettingsSchema.safeParse({ timeZone }).success, timeZone).toBe(true);
    }
  });

  it("rejects a zone Intl does not recognise", () => {
    for (const timeZone of ["Mars/Olympus", "", "Not a zone"]) {
      expect(organizationSettingsSchema.safeParse({ timeZone }).success, timeZone).toBe(false);
    }
    expect(
      updateOrganizationSchema.safeParse({ orgId: ORG_A, settings: { timeZone: "Mars/Olympus" } })
        .success,
    ).toBe(false);
  });

  it("keeps a settings patch a patch: absent keys are not filled with defaults", () => {
    const parsed = updateOrganizationSchema.parse({
      orgId: ORG_A,
      settings: { digestHourUtc: 5 },
    });

    expect(parsed.settings).toEqual({ digestHourUtc: 5 });
  });
});
EOF
